// @ts-check
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));

/** Absolute path of the monorepo root. */
export const repoRoot = join(here, "..", "..", "..");

/** Where the generated files live, relative to the repo root. */
export const outputs = {
  gd: "apps/game/scripts/generated/palette.gd",
  css: "apps/web/src/app/tokens.css",
  ts: "apps/web/src/lib/token-colors.generated.ts",
  gdDepth: "apps/game/scripts/generated/depth_palette.gd",
  cssDepth: "apps/web/src/app/depth-tokens.css",
  tsDepth: "apps/web/src/lib/depth-colors.generated.ts",
};

/**
 * @typedef {{ name: string, light: string, dark: string, use: string }} Token
 */

/** @returns {Token[]} */
export function loadTokens() {
  const file = join(here, "..", "tokens.json");
  return JSON.parse(readFileSync(file, "utf8")).tokens;
}

const HEADER = "GENERATED by packages/design-tokens (pnpm tokens). Do not edit by hand.";

const constName = (/** @type {string} */ name) => name.toUpperCase().replaceAll("-", "_");

/** @returns {Token[]} The tokens of the depth look (a second set; the web does not use it yet). */
export function loadDepthTokens() {
  const file = join(here, "..", "tokens.json");
  return JSON.parse(readFileSync(file, "utf8")).depth.tokens;
}

/** @param {string} hex @returns {number[]} */
const rgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
/** @param {number[]} c */
const toHex = (c) =>
  `#${c.map((v) => Math.round(v).toString(16).padStart(2, "0")).join("")}`.toUpperCase();
/** @param {string} a @param {string} b @param {number} t */
const mix = (a, b, t) => {
  const [x, y] = [rgb(a), rgb(b)];
  return toHex(x.map((v, i) => v + ((y[i] ?? 0) - v) * t));
};
const darken = (/** @type {string} */ c, /** @type {number} */ t) => mix(c, "#000000", t);
const lighten = (/** @type {string} */ c, /** @type {number} */ t) => mix(c, "#FFFFFF", t);

/**
 * The lips of keys and the front, side, and edge shades of board pieces, computed from the depth
 * tokens so no shade is ever written by hand. Returns tokens with the same shape as the others.
 * @param {Token[]} base
 * @returns {Token[]}
 */
export function deriveDepth(base) {
  const by = Object.fromEntries(base.map((t) => [t.name, t]));
  /** @type {Token[]} */
  const out = [];
  /** @param {string} name @param {string} use @param {(theme: "light" | "dark") => string} make */
  const add = (name, use, make) =>
    out.push({ name, use, light: make("light"), dark: make("dark") });
  const of = (/** @type {string} */ name, /** @type {"light" | "dark"} */ theme) =>
    String(by[name]?.[theme]);
  add("tile-lip", "The visible thickness under a key", (th) => darken(of("tile", th), 0.3));
  add("signal-lip", "The thickness under the primary key", (th) => darken(of("signal", th), 0.26));
  add("ink-lip", "The thickness under a solid ink key", (th) =>
    th === "light" ? lighten(of("ink", th), 0.28) : darken(of("ink", th), 0.35),
  );
  /** @type {[string, number][]} */
  const roles = [
    ["plate", 0.12],
    ["floor", 0.18],
    ["wall", 0.16],
    ["trail", 0.18],
    ["signal", 0.18],
    ["ink", 0.1],
  ];
  for (const [role, edge] of roles) {
    add(`${role}-front`, `Front face of a ${role} piece`, (th) => darken(of(role, th), 0.22));
    add(`${role}-side`, `Side face of a ${role} piece`, (th) => darken(of(role, th), 0.36));
    add(`${role}-edge`, `Lit top edge of a ${role} piece`, (th) => lighten(of(role, th), edge));
  }
  return out;
}

/** @param {Token[]} base */
export function generateDepthGdscript(base) {
  const tokens = [...base, ...deriveDepth(base)];
  const dict = (/** @type {"light" | "dark"} */ theme) =>
    tokens.map((t) => `\t"${t.name}": Color("${t[theme]}"),`).join("\n");
  const vars = tokens
    .map((t) => `static var ${constName(t.name)}: Color = LIGHT["${t.name}"]`)
    .join("\n");
  const applies = tokens.map((t) => `\t${constName(t.name)} = theme["${t.name}"]`).join("\n");
  return `# ${HEADER}
class_name DepthPalette
extends RefCounted
## Color tokens for the depth look, light and dark, with the shades computed from them.
## Call apply(dark) to switch. Never mix with Palette on one screen.

const LIGHT := {
${dict("light")}
}
const DARK := {
${dict("dark")}
}

${vars}


static func apply(dark: bool) -> void:
	var theme: Dictionary = DARK if dark else LIGHT
${applies}
`;
}

/**
 * The depth values of the names the flat palette also has, so the whole interface changes color
 * when the look is depth (the depth ground is a gradient; its top color stands in for `ground`).
 * @param {Token[]} tokens
 * @param {Token[]} depth
 * @returns {Token[]}
 */
export function depthOverrides(tokens, depth) {
  const flat = new Set(tokens.map((t) => t.name));
  return depth.flatMap((t) => {
    const name = t.name === "ground-top" ? "ground" : t.name;
    return flat.has(name) ? [{ ...t, name }] : [];
  });
}

/**
 * @param {Token[]} tokens
 * @param {Token[]} [depth] the depth tokens; their shared names override the flat ones when the
 *   look is depth
 */
export function generateGdscript(tokens, depth = []) {
  const dict = (/** @type {"light" | "dark"} */ theme, /** @type {Token[]} */ list = tokens) =>
    list.map((t) => `\t"${t.name}": Color("${t[theme]}"),`).join("\n");
  const vars = tokens
    .map((t) => `static var ${constName(t.name)}: Color = LIGHT["${t.name}"]`)
    .join("\n");
  const applies = tokens.map((t) => `\t${constName(t.name)} = theme["${t.name}"]`).join("\n");
  const over = depthOverrides(tokens, depth);
  return `# ${HEADER}
class_name Palette
extends RefCounted
## Color tokens for the light and dark themes. Call apply(dark) to switch; apply(dark, true) uses
## the depth look's values for the names it shares (see DepthPalette for its own).

const LIGHT := {
${dict("light")}
}
const DARK := {
${dict("dark")}
}
const DEPTH_LIGHT := {
${dict("light", over)}
}
const DEPTH_DARK := {
${dict("dark", over)}
}

${vars}


static func apply(dark: bool, depth: bool = false) -> void:
	var theme: Dictionary = DARK if dark else LIGHT
	if depth:
		theme = theme.merged(DEPTH_DARK if dark else DEPTH_LIGHT, true)
${applies}
`;
}

/**
 * The depth look as CSS for the public site. Everything is scoped to `.look-depth`, so the admin
 * dashboard keeps the flat tokens. The names the flat set shares are overridden (`ground` takes the
 * top color of the gradient) and the depth-only names and derived shades are added, with Tailwind
 * color names for the ones the flat theme does not already map.
 * @param {Token[]} tokens the flat tokens
 * @param {Token[]} depth the depth tokens
 */
export function generateDepthCss(tokens, depth) {
  const all = [...depth, ...deriveDepth(depth)];
  const over = depthOverrides(tokens, depth);
  const flat = new Set(tokens.map((t) => t.name));
  // A shared name is written once, with its depth value; the rest are the depth-only names.
  const written = new Set(over.map((t) => t.name));
  const decls = (/** @type {"light" | "dark"} */ theme, /** @type {string} */ indent) =>
    [
      `${indent}color-scheme: ${theme};`,
      ...over.map((t) => `${indent}--${t.name}: ${t[theme]};`),
      ...all.filter((t) => !written.has(t.name)).map((t) => `${indent}--${t.name}: ${t[theme]};`),
    ].join("\n");
  const theme = all
    .filter((t) => !flat.has(t.name))
    .map((t) => `  --color-${t.name}: var(--${t.name});`)
    .join("\n");
  return `/* ${HEADER} */

@theme inline {
${theme}
}

.look-depth {
${decls("light", "  ")}
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .look-depth {
${decls("dark", "    ")}
  }
}

:root[data-theme="dark"] .look-depth {
${decls("dark", "  ")}
}
`;
}

/**
 * The depth colors as a TypeScript module, for code that cannot use CSS variables (the share image
 * and other generated images). Base tokens and derived shades, in both themes.
 * @param {Token[]} depth
 */
export function generateDepthTypescript(depth) {
  const all = [...depth, ...deriveDepth(depth)];
  const camel = (/** @type {string} */ name) =>
    name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  const dict = (/** @type {"light" | "dark"} */ theme) =>
    all.map((t) => `    ${camel(t.name)}: "${t[theme]}",`).join("\n");
  return `// ${HEADER}

export const DEPTH_COLORS = {
  light: {
${dict("light")}
  },
  dark: {
${dict("dark")}
  },
} as const;
`;
}

/** @param {Token[]} tokens */
export function generateCss(tokens) {
  const block = (/** @type {"light" | "dark"} */ theme, /** @type {string} */ indent) =>
    [`${indent}color-scheme: ${theme};`]
      .concat(tokens.map((t) => `${indent}--${t.name}: ${t[theme]};`))
      .join("\n");
  return `/* ${HEADER} */

:root {
${block("light", "  ")}
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
${block("dark", "    ")}
  }
}

:root[data-theme="dark"] {
${block("dark", "  ")}
}
`;
}

/**
 * The same values as a TypeScript module, for code that cannot use CSS variables: generated
 * images (icons, the share image) and the manifest and theme-color metadata.
 * @param {Token[]} tokens
 */
export function generateTypescript(tokens) {
  const camel = (/** @type {string} */ name) =>
    name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  const dict = (/** @type {"light" | "dark"} */ theme) =>
    tokens.map((t) => `    ${camel(t.name)}: "${t[theme]}",`).join("\n");
  return `// ${HEADER}

export const TOKEN_COLORS = {
  light: {
${dict("light")}
  },
  dark: {
${dict("dark")}
  },
} as const;
`;
}

/** @param {string} hex */
function luminance(hex) {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  const f = (/** @type {number} */ c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
}

/**
 * WCAG contrast ratio between two #RRGGBB colors.
 * @param {string} a
 * @param {string} b
 */
export function contrast(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}
